<script setup lang="ts">
import { t } from '../../i18n';
import type { PdbReference } from '../../v2/workbench';
import ReviewHint from './ReviewHint.vue';
import ResearchProfile from './ResearchProfile.vue';
import { abstractStatusLabels, type ResearchProfile as ResearchProfileData } from './articleMetadata';
defineProps<{metadata:{abstract?:string|null;abstract_source?:string|null;pdb_references?:PdbReference[];pmid?:string|null;pmcid?:string|null;identifiers_source?:string|null;abstract_status?:keyof typeof abstractStatusLabels;abstract_note?:string|null;research_profile?:ResearchProfileData}}>();
const usageLabels = {this_work:'本文结构',cited_structure:'引用结构',unknown:'用途待核对'};
</script>
<template><section class="article-metadata"><div v-if="metadata.pmid || metadata.pmcid" class="identifier-links"><a v-if="metadata.pmid" data-pmid-link :href="`https://pubmed.ncbi.nlm.nih.gov/${encodeURIComponent(metadata.pmid)}/`" target="_blank" rel="noopener">PMID: {{metadata.pmid}} ↗</a> <a v-if="metadata.pmcid" :href="`https://pmc.ncbi.nlm.nih.gov/articles/${encodeURIComponent(metadata.pmcid)}/`" target="_blank" rel="noopener">PMCID: {{metadata.pmcid}} ↗</a><small v-if="metadata.identifiers_source">{{t('标识来源')}}：{{metadata.identifiers_source}}</small></div>
<h3>Abstract</h3><p data-abstract-status>{{ t(metadata.abstract && (!metadata.abstract_status || metadata.abstract_status === 'not_checked') ? '已记录，检查状态未标注' : metadata.abstract_status ? abstractStatusLabels[metadata.abstract_status] : '尚未检查') }}</p><p v-if="metadata.abstract_note">{{metadata.abstract_note}}</p><p class="preserve-lines" data-article-abstract>{{ metadata.abstract || (metadata.abstract_status === 'not_found' ? '—' : t('尚未记录摘要')) }}</p><small v-if="metadata.abstract_source">{{ t('摘要来源') }}：{{ metadata.abstract_source }}</small><ResearchProfile v-if="metadata.research_profile" :profile="metadata.research_profile" /><h3>PDB</h3><p v-if="!metadata.pdb_references?.length">{{ t('尚未记录 PDB ID；空白不表示文章一定未报告。') }}</p><ul v-else><li v-for="(entry,index) in metadata.pdb_references" :key="index"><a :href="`https://www.rcsb.org/structure/${encodeURIComponent(entry.pdb_id)}`" target="_blank" rel="noopener">{{ entry.pdb_id }} ↗</a> · {{ t(usageLabels[entry.usage]) }}<span v-if="entry.source_page"> · p. {{ entry.source_page }}</span><span v-if="entry.compound_label"> · Compound {{ entry.compound_label }}</span><p v-if="entry.source_context">{{ entry.source_context }}</p><ReviewHint :hint="entry.review_hint" /></li></ul></section></template>

<style scoped> .identifier-links small {display:block;color:var(--ink-muted)} .identifier-links a {margin-right:1rem} </style>
